import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Order","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/order.md","filePath":"03-developer/models/order.md"}`),a={name:`03-developer/models/order.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h1><p>The <code>Order</code> model stores one row of order items. Each record is associated with an invoice and a product, and stores information such as the quantity, selected inventory item, and total amount for that row.</p><p>An invoice can have multiple orders; the overall payment and invoice information is stored in the <a href="./invoice.html">Invoice</a> model.</p><h2 id="orders-table-structure" tabindex="-1"><code>orders</code> table structure <a class="header-anchor" href="#orders-table-structure" aria-label="Permalink to “orders table structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Order ID</td></tr><tr><td><code>invoice_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the associated invoice; related to the <code>invoices</code> table</td></tr><tr><td><code>product_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the ordered product; related to the <code>products</code> table</td></tr><tr><td><code>quantity_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the selected inventory item or product type; related to the <a href="./quantity.html">Quantity</a> model</td></tr><tr><td><code>count</code></td><td>INT</td><td>Yes</td><td>Number of units ordered of the product or selected inventory item; defaults to <code>1</code></td></tr><tr><td><code>price_total</code></td><td>DECIMAL(20,2) UNSIGNED</td><td>No</td><td>Total amount for this order row, equal to the quantity multiplied by the unit price</td></tr><tr><td><code>data</code></td><td>LONGTEXT</td><td>Yes</td><td>The selected inventory item&#39;s (<code>prop</code>) properties as JSON, for convenient access when displaying them as a group</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last update time</td></tr></tbody></table><h2 id="relationships-and-methods" tabindex="-1">Relationships and methods <a class="header-anchor" href="#relationships-and-methods" aria-label="Permalink to “Relationships and methods”">​</a></h2><h3 id="product" tabindex="-1"><code>product()</code> <a class="header-anchor" href="#product" aria-label="Permalink to “product()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./product.html">Product</a> model and returns the product associated with the order row.</p><h3 id="quantity" tabindex="-1"><code>quantity()</code> <a class="header-anchor" href="#quantity" aria-label="Permalink to “quantity()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./quantity.html">Quantity</a> model and returns the inventory item or type selected for the product.</p><p>Since <code>quantity_id</code> can be <code>NULL</code>, an order is not necessarily associated with a <code>Quantity</code> record.</p><h3 id="invoice" tabindex="-1"><code>invoice()</code> <a class="header-anchor" href="#invoice" aria-label="Permalink to “invoice()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./invoice.html">Invoice</a> model and returns the invoice associated with the order.</p><h2 id="database-notes" tabindex="-1">Database notes <a class="header-anchor" href="#database-notes" aria-label="Permalink to “Database notes”">​</a></h2><ul><li>The <code>data</code> field is validated using the <code>CHECK (json_valid(data))</code> constraint; therefore, any non-<code>NULL</code> value must be valid JSON.</li><li>Deleting an invoice also deletes its dependent orders; the <code>invoice_id</code> relationship has <code>ON DELETE CASCADE</code>.</li><li>Deleting a product also deletes its dependent orders; the <code>product_id</code> relationship has <code>ON DELETE CASCADE</code>.</li><li>The provided SQL does not define a foreign key for <code>quantity_id</code>; therefore, this database definition does not ensure referential integrity with the inventory table.</li><li>Although <code>count</code> defaults to <code>1</code>, it still accepts <code>NULL</code>. This is meaningless for virtual products.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};